head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stockSearch.js");
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gTrnsType;
scwin.gAllChk = false;
scwin.vScrenID = "ULDSTF30310.xml";
scwin.etfChrgLst = "51,52,53,61,62,63";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.gTrnsType = $c.frame.path("../").scwin.gTrnsType;
    dts_EMP_NO.DataID = "/CodeAction.do?method=getEmpNoDepCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_EMP_NO.Reset();
    dts_DEP_CD.DataID = "/CodeAction.do?method=getDepUpCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_DEP_CD.Reset();
    if (scwin.gTrnsType == 'N') {
        // 쪽지에서 사용
        dts_CORP_USR_TP_CD.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT&FOR=R&CD_ENG_NM=CORP_USR_TP_CD";
        dts_CORP_USR_TP_CD.Reset();
    } else {
        // 메일및문자에서 사용
        // 코스닥은 '공시담당자 + 공시실무자'도 콤보 목록에 표시
        var methodGbn;
        if (scwin.gLdMktTp == '2') {
            methodGbn = "listKosdaqChrgCodeValueName";
        } else {
            methodGbn = "listCodeValueName";
        }

        //dts_chrg_tp.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT&FOR=R&CD_ENG_NM=CHRG_TP_CD" ;
        dts_chrg_tp.DataID = "/CodeAction.do?method=" + methodGbn + "&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT&FOR=R&CD_ENG_NM=CHRG_TP_CD";
        dts_chrg_tp.Reset();
    }

    // 소속부구분 콤보박스 셋팅
    dts_SECT_TP_CD.DataID = "/CodeAction.do?method=getSectTpCd&inputMessageId=CODE_OUT&outputMessageId=CODE_OUT&FOR=R&CD_ENG_NM=SECT_TP_CD";
    dts_SECT_TP_CD.Reset();
};
scwin.initPage = function(mktcd) {
    if (mktcd == '1') {
        // 유가일 경우 소속부 검색 조건을 hidden 처리함
        $c.stf.showObj(label_5, false);
        $c.stf.showObj(cmb_SECT_TP_CD, false);
        cmb_DEP_CD.setDisabled(false);
        cmb_EMP_NO.setDisabled(false);
        $c.stf.showObj(panel_bnd_yn, false);
        $c.stf.setObjectValue(cmb_bnd_yn, '');
    } else if (mktcd == '4') {
        // 채권일 경우 소속부 검색 조건을 hidden 처리함
        cmb_SECT_TP_CD.setDisabled(true);
        cmb_DEP_CD.setDisabled(true);
        cmb_EMP_NO.setDisabled(true);
        $c.stf.showObj(panel_bnd_yn, true);
        $c.stf.setObjectValue(cmb_bnd_yn, 'N');
    } else {
        $c.stf.showObj(label_5, true);
        $c.stf.showObj(cmb_SECT_TP_CD, true);
        cmb_SECT_TP_CD.setDisabled(false);
        cmb_DEP_CD.setDisabled(false);
        cmb_EMP_NO.setDisabled(false);
        $c.stf.showObj(panel_bnd_yn, false);
        $c.stf.setObjectValue(cmb_bnd_yn, '');
    }
};
scwin.fn_Confirm = function() {
    // opener에 값 선택된 값 전달.

    var total = 0;
    for (var i = 1; i <= dts_Note_Receiver.getTotalRow(); i++) {
        var chk = dts_Note_Receiver.getCellData(i, "CHECK");
        /*
        var vCOM_ABBRV = dts_Note_Receiver.NameString(i, "COM_ABBRV");
        var vCORP_USR_NM = dts_Note_Receiver.NameString(i, "CORP_USR_NM");
        var vCELLPHONE_NO = dts_Note_Receiver.NameString(i, "CELLPHONE_NO");
        alert("i=" + i + ", "+ chk + ", " + vCOM_ABBRV + ", vCORP_USR_NM="+vCORP_USR_NM+ ", vCELLPHONE_NO="+vCELLPHONE_NO);
        */
        if (chk == "T" || chk == "1") total++;
    }
    if (total == 0) {
        $c.win.alert("수신자를 선택하세요.");
        return false;
    }
    if (scwin.gTrnsType == 'N') {
        // 쪽지 발송	

        frame.opener.dts_Note_Receiver.ClearData();
        frame.opener.grd_Note_Receiver.setBroadcast(false);
        var j = 1;
        for (var i = 1; i <= dts_Note_Receiver.getTotalRow(); i++) {
            var chk = dts_Note_Receiver.getCellData(i, "CHECK");
            if (chk == "T" || chk == "1") {
                frame.opener.dts_Note_Receiver.AddRow();
                frame.opener.dts_Note_Receiver.setCellData(j, "CHECK", "T");
                frame.opener.dts_Note_Receiver.setCellData(j, "COM_NM", dts_Note_Receiver.getCellData(i, "COM_NM"));
                frame.opener.dts_Note_Receiver.setCellData(j, "EMP_NM", dts_Note_Receiver.getCellData(i, "CORP_USR_NM"));
                frame.opener.dts_Note_Receiver.setCellData(j, "CELLPHONE_NO", dts_Note_Receiver.getCellData(i, "CELLPHONE_NO"));
                frame.opener.dts_Note_Receiver.setCellData(j, "CORP_USR_TP_NM", dts_Note_Receiver.getCellData(i, "CORP_USR_TP_NM"));
                frame.opener.dts_Note_Receiver.setCellData(j, "CORP_USR_TP_CD", dts_Note_Receiver.getCellData(i, "CORP_USR_TP_CD"));
                frame.opener.dts_Note_Receiver.setCellData(j, "ISUR_CD", dts_Note_Receiver.getCellData(i, "ISUR_CD"));
                frame.opener.dts_Note_Receiver.setCellData(j, "INTEG_USR_ID", dts_Note_Receiver.getCellData(i, "INTEG_USR_ID"));
                j++;
            }
        }
        frame.opener.grd_Note_Receiver.setBroadcast(true);
        //frame.opener.grd_Note_Receiver.AutoResizeAllCol(true);

    } else if (scwin.gTrnsType == 'M' || scwin.gTrnsType == 'QM') {
        // 메일서비스일때...

        //frame.opener.dts_Receiver.ClearData();
        //var j = 1 ;
        frame.opener.grd_Receiver.setBroadcast(false);
        var j = 1 + frame.opener.dts_Receiver.getTotalRow();
        for (var i = 1; i <= dts_Note_Receiver.getTotalRow(); i++) {
            var chk = dts_Note_Receiver.getCellData(i, "CHECK");
            var vLength = dts_Note_Receiver.getCellData(i, "EMAIL").length;
            if (vLength > 0 && (chk == "T" || chk == "1")) {
                frame.opener.dts_Receiver.AddRow();
                frame.opener.dts_Receiver.setCellData(j, "CHECK", "T");
                frame.opener.dts_Receiver.setCellData(j, "COM_ABBRV", dts_Note_Receiver.getCellData(i, "COM_ABBRV"));
                frame.opener.dts_Receiver.setCellData(j, "CHRG_NM", dts_Note_Receiver.getCellData(i, "CHRG_NM"));
                frame.opener.dts_Receiver.setCellData(j, "EMAIL", dts_Note_Receiver.getCellData(i, "EMAIL"));
                frame.opener.dts_Receiver.setCellData(j, "ISUR_CD", dts_Note_Receiver.getCellData(i, "ISUR_CD"));
                frame.opener.dts_Receiver.setCellData(j, "INTEG_USR_ID", dts_Note_Receiver.getCellData(i, "INTEG_USR_ID"));
                j++;
            }
        }

        //frame.opener.grd_Receiver.AutoResizeAllCol(true);
        frame.opener.grd_Receiver.setBroadcast(true);
    } else if (scwin.gTrnsType == 'S') {
        //  문자서비스일때...

        frame.opener.grd_Receiver.setBroadcast(false);

        //frame.opener.dts_Receiver.ClearData();
        //var j = 1 ;
        var j = 1 + frame.opener.dts_Receiver.getTotalRow();
        for (var i = 1; i <= dts_Note_Receiver.getTotalRow(); i++) {
            var chk = dts_Note_Receiver.getCellData(i, "CHECK");
            var vLength = dts_Note_Receiver.getCellData(i, "CELLPHONE_NO").length;
            if (vLength > 0 && (chk == "T" || chk == "1")) {
                frame.opener.dts_Receiver.AddRow();
                frame.opener.dts_Receiver.setCellData(j, "CHECK", "T");
                frame.opener.dts_Receiver.setCellData(j, "COM_ABBRV", dts_Note_Receiver.getCellData(i, "COM_ABBRV"));
                frame.opener.dts_Receiver.setCellData(j, "CHRG_NM", dts_Note_Receiver.getCellData(i, "CHRG_NM"));
                frame.opener.dts_Receiver.setCellData(j, "CELLPHONE_NO", dts_Note_Receiver.getCellData(i, "CELLPHONE_NO"));
                frame.opener.dts_Receiver.setCellData(j, "ISUR_CD", dts_Note_Receiver.getCellData(i, "ISUR_CD"));
                frame.opener.dts_Receiver.setCellData(j, "INTEG_USR_ID", dts_Note_Receiver.getCellData(i, "INTEG_USR_ID"));
                frame.opener.dts_Receiver.setCellData(j, "EMAIL", dts_Note_Receiver.getCellData(i, "EMAIL"));
                j++;
            }
        }
        //frame.opener.grd_Receiver.AutoResizeAllCol(true);
        frame.opener.grd_Receiver.setBroadcast(true);
        frame.opener.fn_RowCount();
    }
    return true;
};
scwin.fn_SelectAll = function() {
    grd_Note_Receiver.Redraw = false;
    grd_Mail_Receiver.Redraw = false;
    if (scwin.gAllChk == false) {
        // 현재상태가 false이면 전체선택을 클릭릭한것

        scwin.gAllChk = true;
        for (var i = 0; i < dts_Note_Receiver.getTotalRow(); i++) {
            dts_Note_Receiver.setCellData(i + 1, "CHECK", "T");
        }
        btn_SelectedAll.setValue("전체해제");
    } else {
        // 현재상태가  true이면 전체선택을 클릭한것
        scwin.gAllChk = false;
        for (var i = 0; i < dts_Note_Receiver.getTotalRow(); i++) {
            dts_Note_Receiver.setCellData(i + 1, "CHECK", "F");
        }
        btn_SelectedAll.setValue("전체선택");
    }
    grd_Note_Receiver.Redraw = true;
    grd_Mail_Receiver.Redraw = true;
};
scwin.fn_listReceiptPlace = function() {
    // 초기화 
    scwin.gAllChk == false;
    btn_SelectedAll.setValue("전체선택");
    var url = "";
    if (scwin.gTrnsType == 'N') {
        // 쪽지 받는곳 찾기
        url = "/NoteMgt.do?method=listReceiptPlace";
        url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd);
        url += "&DEP_CD=" + $c.stf.getObjectValue(cmb_DEP_CD);
        url += "&EMP_NO=" + $c.stf.getObjectValue(cmb_EMP_NO);
        url += "&CORP_USR_TP_CD=" + $c.stf.getObjectValue(cmb_CORP_USR_TP_CD);
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    } else {
        var questNo = '';
        var gQUEST_PROG_STAT_CD = '';
        if (scwin.gTrnsType == 'QM') {
            // 설문메일서비스일때...
            questNo = $c.frame.path("../").questNo;
            gQUEST_PROG_STAT_CD = $c.stf.getObjectValue($c.frame.path("../").rdo_QUEST_PROG_STAT_CD);
            if (questNo == '') {
                $c.win.alert("수신자를 파라미터를 찾을 수 없습니다.");
                return;
            }
        }
        var chrgTpCd = $c.stf.getObjectValue(cmb_chrg_tp);
        if (chrgTpCd == "" && js_dep_cd.substr(0, 2) == '2B') {
            chrgTpCd = "ETF";
        }


        // 이메일 및 문자  받는곳 찾기
        url = "/EmailMgt.do?method=listReceiptPlace";
        url += "&inputMessageId=MAIL_RECEIPTPLACE_IN&outputMessageId=MAIL_RECEIPTPLACE_OUT";
        url += "&TRANS_TYPE=" + scwin.gTrnsType;
        url += "&QUEST_NO=" + questNo;
        url += "&QUEST_PROG_STAT_CD=" + gQUEST_PROG_STAT_CD;
        url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd);
        url += "&DEP_CD=" + $c.stf.getObjectValue(cmb_DEP_CD);
        url += "&EMP_NO=" + $c.stf.getObjectValue(cmb_EMP_NO);
        url += "&CHRG_TP_CD=" + chrgTpCd;
        url += "&MKT_TP_CD=" + scwin.gLdMktTp;
        url += "&ACNTCLS_MM=" + $c.stf.getObjectValue(cmb_month);
        url += "&SECT_TP_CD=" + $c.stf.getObjectValue(cmb_SECT_TP_CD);
        url += "&CHRG_MKT_CD=" + $c.stf.getObjectValue(rdo_MKT_ID); //시장구분추가 20180727
        url += "&BND_YN=" + $c.stf.getObjectValue(cmb_bnd_yn); //채권상장법인여부 추가 20190927
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    }
    $c.cm.ShowWin(grd_Mail_Receiver);
    dts_Note_Receiver.DataID = encodeURI(url);
    dts_Note_Receiver.Reset();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.cmb_DEP_CD_OnSelChange = function() {
    scwin.gDepCd = $c.stf.getObjectValue(cmb_DEP_CD); //;.ValueOfIndex("VALUE", cmb_DEP_CD.Index);

    dts_EMP_NO.UseFilter = true;
    dts_EMP_NO.Filter();
};
scwin.dts_EMP_NO_OnFilter = function(row) {
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_EMP_NO.getCellData(row, "dep_cd") == scwin.gDepCd ||
            dts_EMP_NO.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.btn_Confirm_onclick = async function() {
    if (scwin.fn_Confirm() == true) {
        await $c.frame.CloseFrame();
    }
};
scwin.btn_Search_onclick = function() {
    scwin.fn_listReceiptPlace();
};
scwin.dts_Note_Receiver_OnLoadCompleted = function(rowcount) {
    $c.stf.setObjectValue(txb_totCnt, "총건수 : " + rowcount);
    $c.cm.CloseWin(rowcount, grd_Mail_Receiver);
};
scwin.dts_Note_Receiver_OnLoadError = function() {
    $c.stf.alert_error(dts_Note_Receiver);
};
scwin.dts_chrg_tp_OnLoadCompleted = function(rowcount) {
    // 데이터셋 복사
    $c.stf.CopyDataSet(dts_chrg_tp, dts_chrg_tp1);
    if (js_dep_cd.substr(0, 1) == '5' || scwin.gLdMktTp == '9') {
        for (var i = 0; i < dts_chrg_tp1.getTotalRow(); i++) {
            if (dts_chrg_tp1.getCellData(i, "value").substr(0, 1) == '1') {
                dts_chrg_tp1.setCellData(i, "text", '[유]' + dts_chrg_tp1.getCellData(i, "text"));
            } else if (dts_chrg_tp1.getCellData(i, "value").substr(0, 1) == '4') {
                dts_chrg_tp1.setCellData(i, "text", '[코]' + dts_chrg_tp1.getCellData(i, "text"));
            }
        }
    }
    dts_chrg_tp1.UseFilter = true;
    dts_chrg_tp1.Filter();
};
scwin.dts_chrg_tp1_OnFilter = function(row) {
    if (scwin.gLdMktTp == '1') {
        // 유가 

        if ((js_dep_cd.substr(0, 2) == '2B')) {
            if (scwin.etfChrgLst.indexOf(dts_chrg_tp1.getCellData(row, "value")) != -1) {
                return true;
            } else {
                return false;
            }
        } else {
            if (dts_chrg_tp1.getCellData(row, "value").substr(0, 1) != '4') {
                return true;
            } else {
                return false;
            }
        }
    } else if (scwin.gLdMktTp == '2') {
        // 코스닥 

        if (js_dep_cd == '3230') {
            //시장마케팅팀
            if (dts_chrg_tp1.getCellData(row, "value").substr(0, 1) == '4' ||
                dts_chrg_tp1.getCellData(row, "value").substr(0, 1) == '') {
                return true;
            } else {
                return false;
            }
        } else {
            // 코스닥은 IR담당자(45)를 볼 수 없음  20151002
            if ((dts_chrg_tp1.getCellData(row, "value").substr(0, 1) == '4' && dts_chrg_tp1.getCellData(row, "value").substr(0, 2) != '45') ||
                dts_chrg_tp1.getCellData(row, "value").substr(0, 1) == '') {
                return true;
            } else {
                return false;
            }
        }
    } else if (scwin.gLdMktTp == '6') {
        // 코넥스
        if (dts_chrg_tp1.getCellData(row, "value").substr(0, 1) == '8' || dts_chrg_tp1.getCellData(row, "value").substr(0, 1) == '') {
            return true;
        } else {
            return false;
        }
    } else if (scwin.gLdMktTp == '4') {
        // 채권
        if (dts_chrg_tp1.getCellData(row, "value").substr(0, 1) == '7' || dts_chrg_tp1.getCellData(row, "value").substr(0, 1) == '') {
            return true;
        } else {
            return false;
        }
    } else if (scwin.gLdMktTp == '9') {
        //시스템 관리자는 목록 다 봄
        return true;
    } else {
        // 그외 IR담당자 목록을 볼 수 없음
        if (dts_chrg_tp1.getCellData(row, "value").substr(0, 2) == '45') {
            return false;
        } else {
            return true;
        }
    }
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.img_com_srch_onclick = function() {
    if (scwin.gLdMktTp == '9') {
        $c.cm.IsurcdSearch_all(txb_isur_cd, txb_com_abbrv);
    } else if (js_dep_cd.substr(0, 2) == '2B') {
        $c.stockSearch.JongmokSearch(txb_isur_cd, txb_com_abbrv, 'EF', js_market, "A");
    } else {
        $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.btn_SelectedAll_onclick = function() {
    scwin.fn_SelectAll();
};
scwin.rdo_MKT_ID_OnSelChange = function() {
    var rdo_MKT = $c.stf.getObjectValue(rdo_MKT_ID);
    scwin.initPage(rdo_MKT);
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    $c.stf.showObj(panel_2, false);
    $c.stf.showObj(panel_3, false);
    $c.stf.showObj(label_2, false);
    $c.stf.showObj(grd_Note_Receiver, false);
    $c.stf.showObj(grd_Mail_Receiver, false);
    $c.stf.showObj(panel_mkt, false);
    $c.stf.showObj(panel_bnd_yn, false);


    //if (js_dep_cd == '3G10')  { //성장기업부 - MnA팀 20180727 요청
    if (js_dep_cd == '3G30') {
        //성장기업팀(3G10) > 혁신성장지원실 (3G00)
        scwin.gLdMktTp = '9';
    }

    /*if (gLdMktTp == '1' ) {	// 유가일 경우 소속부 검색 조건을 hidden 처리함
    	showObj(label_5, false);	
    	showObj(cmb_SECT_TP_CD, false);	
    }
    else if (gLdMktTp == '4' ) {	// 채권일 경우 소속부 검색 조건을 hidden 처리함
    	cmb_SECT_TP_CD.enable2 = false;
    	cmb_DEP_CD.enable2 = false;
        cmb_EMP_NO.enable2 = false;
    	showObj(panel_bnd_yn, true);
    	setObjectValue(cmb_bnd_yn, 'N');
    }*/

    scwin.fn_SetCode();
    scwin.initPage(scwin.gLdMktTp); //hidden 처리

    //시장감시부
    if (js_dep_cd.substr(0, 1) == '5') {
        $c.stf.showObj(panel_TEAM, false);
    }
    if (scwin.gTrnsType == 'N') {
        // 쪽지에서 사용
        $c.stf.showObj(panel_2, true);
        $c.stf.SetWindowPos2(panel_2, 10, 60);
        $c.stf.showObj(grd_Note_Receiver, true);
        $c.stf.showObj(label_2, true);
    } else {
        $c.stf.showObj(panel_3, true);
        $c.stf.showObj(grd_Mail_Receiver, true);
        $c.stf.showObj(label_2, false);
        if (scwin.gLdMktTp == '9') {
            $c.stf.showObj(panel_mkt, true);
        }
        if (scwin.gTrnsType == 'M' || scwin.gTrnsType == 'QM') {
            // 메일서비스일때...
            $c.stf.setObjectValue(txb_msg, "※ 담당자정보의 이메일주소가 없으면 발송되지 않습니다.");
        } else if (scwin.gTrnsType == 'S') {
            // 문자서비스일때...
            $c.stf.setObjectValue(txb_msg, "※ 담당자정보의 휴대폰번호가 없으면 발송되지 않습니다.");
        }
    }
    if (scwin.gLdMktTp == '9') {
        $c.cm.fn_com_isur_all(txb_isur_cd, txb_com_abbrv);
    } else {
        $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    }
};
